package org.apache.commons.math3.optim.nonlinear.vector;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.linear.DiagonalMatrix;
import org.apache.commons.math3.linear.MatrixUtils;
import org.apache.commons.math3.linear.NonSquareMatrixException;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.optim.OptimizationData;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for Weight constructor.
 */
public class Weight_Weight_TriageGen2Test {







    @Test
    public void testWeightConstructorWithRealMatrix() {
        double[][] data = {
            {1.0, 0.5},
            {0.5, 1.0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        Weight weight = new Weight(matrix);

        RealMatrix resultMatrix = weight.getWeight();

        Assert.assertEquals(2, resultMatrix.getRowDimension());
        Assert.assertEquals(1.0, resultMatrix.getEntry(0, 0), 1e-10);
        Assert.assertEquals(0.5, resultMatrix.getEntry(0, 1), 1e-10);
        Assert.assertEquals(0.5, resultMatrix.getEntry(1, 0), 1e-10);
        Assert.assertEquals(1.0, resultMatrix.getEntry(1, 1), 1e-10);
    }




}

